+
+func parseBoolOptionValue(raw string) (bool, bool) {
+	value := strings.TrimSpace(strings.ToLower(raw))
+	switch value {
+	case "1", "true", "yes", "on":
+		return true, true
+	case "0", "false", "no", "off":
+		return false, true
+	default:
+		return false, false
+	}
+}
+
+func parseInvocationOptions(args []string) invocationOptions {
+	options := invocationOptions{}
